#!/bin/bash
# promptfoo-style custom provider: shells out to the real `opencode` CLI,
# using this repo's actual generated .opencode/agents/<role>.md as the agent
# under test.
#
# --- Phase-2 spike findings (verified, see
# docs/concepts/planned/orchestrator-routing-test-suite.md Sec. 5) ---
#
# 1. `opencode run --agent <name>` only works for agents with `mode: primary`
#    in their frontmatter. Every agent generated by sync.py under
#    .opencode/agents/*.md has `mode: subagent`. Workaround: copy the role
#    file into an isolated dir with `mode: primary` and run there via --dir.
# 2. Default model: paid `opencode-go/deepseek-v4-flash` (stable; the free
#    variant had an unreachable upstream during the spike). Override via
#    OPENCODE_ROUTING_EVAL_MODEL.
# 3. `--format json` streams NDJSON. The model answer is in `part.text` of
#    the LAST event with `"type":"text"`.
#
# v2 (issue #535, resolving findings #523):
#   * --agent <role> : any generated role, not just orchestrator.
#     Missing/unknown role => exit 2 (finding W6: silent exit 0 turned a
#     typo'd role into an all-FAIL sweep instead of a loud infra error).
#   * Structured sidecar (finding B1): stdout stays final_text for backward
#     compatibility, but when EVAL_STRUCTURED_OUTPUT is set, a JSON object is
#     written there carrying final_text, an event-type histogram,
#     tool_events (type + part.tool when present) and spawn_attempts — so
#     behavioral asserts can distinguish "correctly refused" from "tried and
#     silently failed at infrastructure level".
set -uo pipefail
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"

ROLE="orchestrator"
PROMPT=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --agent)
      ROLE="$2"
      shift 2
      ;;
    --agent=*)
      ROLE="${1#*=}"
      shift
      ;;
    *)
      PROMPT="$1"
      shift
      ;;
  esac
done

SRC_AGENT="$REPO_ROOT/.opencode/agents/${ROLE}.md"
if [[ ! -f "$SRC_AGENT" ]]; then
  echo "provider-opencode: unknown or missing role file: $SRC_AGENT" >&2
  exit 2
fi

RUN_DIR="$(mktemp -d)"
trap 'rm -rf "$RUN_DIR"' EXIT

mkdir -p "$RUN_DIR/.opencode/agents"
sed 's/^mode: subagent$/mode: primary/' "$SRC_AGENT" > "$RUN_DIR/.opencode/agents/${ROLE}.md"

# The whole test's validity rests on this substitution actually landing --
# if sync.py ever changes the frontmatter format, the sed silently no-ops
# and `opencode run` falls back to the generic `build` agent with only a
# stderr warning. Assert it instead.
if ! grep -q '^mode: primary$' "$RUN_DIR/.opencode/agents/${ROLE}.md"; then
  echo "provider-opencode: mode:primary substitution failed on $SRC_AGENT (frontmatter format drift?)" >&2
  exit 2
fi

MODEL="${OPENCODE_ROUTING_EVAL_MODEL:-opencode-go/deepseek-v4-flash}"

# `opencode run` spawns a detached `opencode serve` background process that
# does NOT exit when the run completes. Kill only PIDs that appeared during
# this invocation.
pids_before="$(pgrep -x opencode 2>/dev/null || true)"

raw_output="$(
  cd "$RUN_DIR" && timeout 90 opencode run "$PROMPT" \
    --agent "$ROLE" \
    --format json \
    --model "$MODEL" \
    --dir "$RUN_DIR" 2>/dev/null
)"

pids_after="$(pgrep -x opencode 2>/dev/null || true)"
new_pids="$(comm -13 <(echo "$pids_before" | sort) <(echo "$pids_after" | sort))"
if [[ -n "$new_pids" ]]; then
  # shellcheck disable=SC2086
  kill $new_pids 2>/dev/null || true
fi

STRUCT_OUT="${EVAL_STRUCTURED_OUTPUT:-}"
FINAL_TEXT="$(printf '%s\n' "$raw_output" | ROLE="$ROLE" STRUCT_OUT="$STRUCT_OUT" python3 -c '
import collections
import json
import os
import sys

final_text = None
counts = collections.Counter()
tool_events = []
spawn_attempts = 0

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    try:
        event = json.loads(line)
    except json.JSONDecodeError:
        continue
    etype = event.get("type", "unknown")
    counts[etype] += 1
    if etype == "text":
        text = event.get("part", {}).get("text")
        if text is not None:
            final_text = text
    elif etype not in ("step_start", "step_finish"):
        tool = event.get("part", {}).get("tool") or event.get("tool")
        tool_events.append({"type": etype, "tool": tool})
        if tool == "task" or etype in ("tool_input", "tool_call"):
            spawn_attempts += 1

struct = {
    "provider": "opencode",
    "role": os.environ.get("ROLE", ""),
    "stream": True,
    "final_text": final_text or "",
    "event_counts": dict(counts),
    "tool_events": tool_events,
    "spawn_attempts": spawn_attempts,
}
out_path = os.environ.get("STRUCT_OUT", "")
if out_path:
    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(struct, f, ensure_ascii=False)
print((final_text or "").strip())
')"

printf '%s\n' "$FINAL_TEXT"
